python3 << 'PYEOF'
import json

# Now let me check all the "via" entries from npm audit for all high/critical packages
# to find any direct CVEs we might be missing
with open('/root/npm-audit-results.json') as f:
    data = json.load(f)

vulns = data.get('vulnerabilities', {})
# Collect all direct CVE/advisory entries (not reference strings)
direct_advisories = {}
for pkg_name, info in vulns.items():
    for via in info.get('via', []):
        if isinstance(via, dict):
            sev = via.get('severity', '').upper()
            if sev in ('HIGH', 'CRITICAL'):
                key = (pkg_name, via.get('url', ''))
                if key not in direct_advisories:
                    direct_advisories[key] = via

print(f"Total direct HIGH/CRITICAL advisories from npm audit: {len(direct_advisories)}")
for (pkg, url), via in sorted(direct_advisories.items()):
    print(f"  {pkg}: {via.get('title', '')} | {url} | CVSS: {via.get('cvss', {}).get('score', 'N/A')}")
PYEOF
